import SwiftUI
import UIKit
import WordhoardCore

/// A word row's 44 pt picture (I6, plan 4.4): the cached thumbnail file, decoded off the main actor and
/// regenerated by `ImageStore` when missing. Decorative: the row's headword is what VoiceOver reads.
struct RowThumbnail: View {
    let imageStore: ImageStore
    let fileName: String
    @State private var image: UIImage?

    var body: some View {
        Color.secondary.opacity(0.15)
            .overlay {
                if let image {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                }
            }
            .frame(width: 44, height: 44)
            .clipShape(RoundedRectangle(cornerRadius: 8))
            .accessibilityHidden(true)
            .accessibilityIdentifier("wordList.rowThumbnail")
            .task(id: fileName) {
                let imageStore = imageStore
                let fileName = fileName
                image = await Task.detached(priority: .utility) {
                    guard let url = try? imageStore.thumbnailURL(for: fileName) else {
                        return nil
                    }
                    return UIImage(contentsOfFile: url.path(percentEncoded: false))?.preparingForDisplay()
                }.value
            }
    }
}
